// DeleteAll 删除用户的全部好友（每次请求最多 100 位，SDK 循环到 has_more 为 false）
//
// 每次请求按好友的内部用户 ID 取出最多 100 位逐个删除，返回这次实际删除的人数 deleted_count 和 has_more；
// SDK 循环调用直到 has_more 为 false，返回 deleted_count 的总和。每次请求按取出的人数计入 OpenAPI 额度。
// 双方的关系同时解除，每位好友收到原因为 server 的 friend.removed；已删除、尚未补写删除标记的好友同样删除（这时 friend_username 为空）。
// 中途出错时整个请求返回错误，已删除的不回滚，再次调用即可继续，所以可以重试。只读状态下照常执行。
//
// 接口：DELETE /users/{username}/friends（friends.delete_all）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
//
// SDK 循环调用直到 has_more 为假，返回删除的总数（出错时返回已删除的数和错误）。
func (s *FriendsService) DeleteAll(ctx context.Context, username string) (int, error) {
	total := 0
	for {
		c := s.t.newCall(&endpoints.FriendsDeleteAll)
		c.path("username", username)
		var out struct {
			DeletedCount int  `json:"deleted_count"`
			HasMore      bool `json:"has_more"`
		}
		if err := s.t.do(ctx, c, &out); err != nil {
			return total, err
		}
		total += out.DeletedCount
		if !out.HasMore {
			return total, nil
		}
	}
}

// BatchAdd 批量直接添加好友（每次最多 100 个）
//
// 逐个处理、各项独立成败，整体返回 200；每项的规则与单个添加相同，参数不合法、用户不存在、好友数已满的项出现在 failed 中。
// 已是好友的按修改处理，也出现在 added 中。同一个用户名出现多次时不去重，按出现的次数处理。结果不带 changed 和版本号。
