// Add 直接添加好友（双方同时成为好友）
//
// 服务端添加不检查加好友方式和双方的黑名单，不经过加好友前回调和内容安全；双方的好友数上限照常检查，
// 已满返回 limit_exceeded（details.reason 为 friend_limit 或 peer_friend_limit）。两人之间未过期的待处理申请改为 accepted。
// remark、attributes 只设置 {username} 一侧，没给 remark 时取 {username} 发给对方的待处理申请中预设的备注；对方一侧取对方申请中预设的备注。
// 已是好友时按修改处理：写入这次给出的 remark、attributes（add_source、created_at 忽略），内容有变化时 changed 为 true，所以重复调用时 changed 为 false。
// {friend} 与 {username} 相同返回 invalid_argument；对方被封禁不影响添加。只读状态下返回 app_unavailable。
//
// 接口：PUT /users/{username}/friends/{friend}（friends.add）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *FriendsService) Add(ctx context.Context, username, friend string, params AddFriendParams) (*FriendChange, error) {
	c := s.t.newCall(&endpoints.FriendsAdd)
	c.path("username", username)
	c.path("friend", friend)
	w := c.body()
	w.beginObject()
	if params.Remark != "" {
		w.key("remark")
		encStr(w, params.Remark)
	}
	writeField(w, "attributes", params.Attributes, encFieldMap(encStr))
	if params.AddSource != "" {
		w.key("add_source")
		encStr(w, params.AddSource)
	}
	if !params.CreatedAt.IsZero() {
		w.key("created_at")
		encTime(w, params.CreatedAt)
	}
	w.endObject()
	out := new(FriendChange)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Update 修改好友的备注和自定义属性
//
// 只修改 {username} 一侧，对方看不到。remark、attributes 都没给（remark 为 null 等于没给）时返回 invalid_argument。
// 与原值相同时 changed 为 false、不发布事件，所以重复调用结果相同。不是好友返回 not_found；只读状态下返回 app_unavailable。
