// List 分页列出用户的黑名单（带版本号）
//
// 按被拉黑用户的内部用户 ID 排序。known_version 只在不带 cursor 时生效：与当前版本号相同时只返回 version、not_modified、count、max_count。
// 跳过已删除、清理尚未完成的用户，一页的条数可能少于 limit 甚至为 0，是否还有下一页只看 next_cursor。max_count 固定为 1000。
//
// 接口：GET /users/{username}/blacklist（blacklist.list）。查询，网络错误、超时、5xx 时自动重试。
func (s *BlacklistService) List(ctx context.Context, username string, params ListBlacklistParams) (*VersionedPage[BlacklistEntry], error) {
	c := s.t.newCall(&endpoints.BlacklistList)
	c.path("username", username)
	if params.KnownVersion != nil {
		c.query("known_version", strconv.FormatInt(*params.KnownVersion, 10))
	}
	if params.Cursor != "" {
		c.query("cursor", params.Cursor)
	}
	if params.Limit != 0 {
		c.query("limit", strconv.Itoa(params.Limit))
	}
	out := new(VersionedPage[BlacklistEntry])
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// All 逐项遍历 List 的结果，自动翻页：按 next_cursor 是否为空判断结束，不按条数判断（一页可能为空而仍有下一页）。
// 出错时产出这个错误后结束，已产出的项有效。
// 不带 KnownVersion（遍历要的是全部数据）。
func (s *BlacklistService) All(ctx context.Context, username string, params ListBlacklistParams) iter.Seq2[BlacklistEntry, error] {
	return iterPages(ctx, params.Cursor, func(ctx context.Context, cursor string) ([]BlacklistEntry, string, error) {
		p := params
		p.Cursor = cursor
		p.KnownVersion = nil
		page, err := s.List(ctx, username, p)
		if err != nil {
			return nil, "", err
		}
		return page.Items, page.NextCursor, nil
	})
}

