// Update 修改群资料和设置
//
// 只修改给出的字段；与原值相同的不算变化（changed 为假，不加 info_version）；没有任何要改的字段时返回 invalid_argument。
// 文本字段为 null 与不传相同，清空传空字符串。给出 version 时只有与当前的 info_version 一致才修改，否则 version_conflict。
// 公开群改为私有群时 join_mode 清空、待处理的申请失效；私有群改为公开群时 join_mode 默认为 approval；对私有群（含同时改为私有群）
// 设置 join_mode 返回 invalid_argument。被封禁的群也可以修改（用于清除违规内容），已解散的群返回 not_found。
// 名称、简介、公告和头像经过内容安全检查（只检查真正修改的），可能被替换或返回 content_rejected。只读状态下返回 app_unavailable。
//
// 接口：PATCH /groups/{group_id}（groups.update）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *GroupsService) Update(ctx context.Context, groupID string, params UpdateGroupParams) (*GroupChange, error) {
	c := s.t.newCall(&endpoints.GroupsUpdate)
	c.path("group_id", groupID)
	w := c.body()
	w.beginObject()
	if params.Type != nil {
		w.key("type")
		encStr(w, *params.Type)
	}
	if params.Name != nil {
		w.key("name")
		encStr(w, *params.Name)
	}
	if params.AvatarURL != nil {
		w.key("avatar_url")
		encStr(w, *params.AvatarURL)
	}
	if params.Description != nil {
		w.key("description")
		encStr(w, *params.Description)
	}
	if params.Announcement != nil {
		w.key("announcement")
		encStr(w, *params.Announcement)
	}
	writeField(w, "attributes", params.Attributes, encFieldMap(encStr))
	if params.MemberInvite != nil {
		w.key("member_invite")
		encStr(w, *params.MemberInvite)
	}
	if params.JoinMode != nil {
		w.key("join_mode")
		encStr(w, *params.JoinMode)
	}
	writeField(w, "max_members", params.MaxMembers, encInt)
	if params.Version != nil {
		w.key("version")
		encInt64(w, *params.Version)
	}
	w.endObject()
	out := new(GroupChange)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

