// AddMembers 批量加人（每次最多 100 个，直接入群）
//
// 用户名转为小写、去重后为 1 到 100 个，按去重后的项数计入 OpenAPI 额度；结果按去重后的顺序，同一个事务中完成，member_version 只加 1。
// 直接入群（joined_via 为 server），不检查群的邀请设置、用户的入群邀请方式和用户之间的黑名单，不经过加群前回调；检查群黑名单和上限。
// 逐项为 joined、already_member（重试时已加入的也是它），或失败：not_found（用户不存在）、permission_denied（details.reason 为
// group_blacklisted）、limit_exceeded（group_member_limit、user_group_limit）。群被封禁返回 group_disabled，只读状态下返回 app_unavailable。
//
// 接口：POST /groups/{group_id}/members/batch（groups.add_members）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *GroupsService) AddMembers(ctx context.Context, groupID string, usernames []string) (*GroupMembersResult, error) {
	c := s.t.newCall(&endpoints.GroupsAddMembers)
	c.path("group_id", groupID)
	w := c.body()
	c.require(len(usernames) > 0, "usernames")
	c.maxItems("usernames", len(usernames), 100)
	w.beginObject()
	w.key("usernames")
	encSlice(encStr)(w, usernames)
	w.endObject()
	c.items = len(usernames)
	out := new(GroupMembersResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

