// MessagesService 消息的发送、查询与导出、撤回、编辑、置顶（client.Messages）。
type MessagesService struct {
	t *transport
}

// Send 发送一条消息（单聊或群聊）
//
// to_user、to_group 恰好给一个（否则为 invalid_argument，invalid_recipient）。单聊必须给 from（否则为 from_required）；群聊不给 from 时以系统身份发送。
// 服务端发送不检查用户的禁言和租户封禁、好友关系、双方的黑名单、群的禁言和全员禁言，不按用户限流，@ 全体成员不要求群主或管理员，
// 附件地址只检查格式（不检查是否为本服务的文件，body 中的 url 应是上传得到的文件地址，不是下载地址）。照常检查：平台封禁
// （发送者为 user_disabled、群为 group_disabled，details.disabled_by 为 platform；租户封禁的可以）、from 的群成员身份（not_group_member）、
// 按群和按应用的频率限制（rate_limited，details.reason 为 group_send_rate、app_message_rate）、只读状态（app_unavailable）、
// 内容安全和发消息前回调（拒绝为 message_rejected，也可能替换内容；租户规则只在场景开启了“含服务端发送”时检查）。
// 服务端发送不算发送者已读（发送者原本没有未读时除外），不改变对方看到的已读位置。
// 按“会话、发送者、client_msg_id”去重，没有时间窗口：重复提交返回 200 和第一次写入的消息（即使这次内容不同），
// 去重排在只读状态、频率限制和发送前检查之前；单聊中第一次发送后接收者被删除的，重试得到 not_found。没有给 client_msg_id 时 SDK 生成。
// online_only 为真时只推给在线的设备：不保存、不分配序号、不去重、不发事件，返回 200 和精简结果（online_only 为真，不是重复提交）；
// 重发会让在线的设备收到两次，所以不自动重试，超时后无法确认是否已推送。
// 其他错误：发送者、接收者不存在为 not_found，群不存在或已解散为 not_found；invalid_argument 的 details.reason 为 self_conversation、
// unknown_type、invalid_body（details.field）、invalid_client_msg_id、reserved_client_msg_id、mentions_not_allowed、invalid_reply、
// receipt_not_allowed、invalid_online_only、invalid_push（details.field）；need_receipt 而应用没有开启群已读回执为 permission_denied
// （read_ack_disabled）；内容超过应用的 max_message_body_bytes 为 payload_too_large（details.max_bytes）。
//
// 接口：POST /messages（messages.send）。带幂等键的写操作，用同一个键自动重试。OnlineOnly 为真（只推在线的消息）时不去重，按不幂等处理，不自动重试。
func (s *MessagesService) Send(ctx context.Context, params SendMessageParams) (*SendResult, error) {
	c := s.t.newCall(&endpoints.MessagesSend)
	c.unsafe = params.OnlineOnly
	if (params.ToUser == "") == (params.ToGroup == "") {
		c.fail("to_user", "ToUser 和 ToGroup 必须恰好给一个")
	}
	w := c.body()
	c.require(params.Type != "", "type")
	c.require(params.Body != nil, "body")
	w.beginObject()
	if params.From != "" {
		w.key("from")
		encStr(w, params.From)
	}
	if params.ToUser != "" {
		w.key("to_user")
		encStr(w, params.ToUser)
	}
	if params.ToGroup != "" {
		w.key("to_group")
		encStr(w, params.ToGroup)
	}
	clientMsgID := params.ClientMsgID
	c.checkClientMsgID(clientMsgID)
	if clientMsgID == "" && !c.unsafe {
		clientMsgID = newClientMsgID()
	}
	if clientMsgID != "" {
		w.key("client_msg_id")
		encStr(w, clientMsgID)
	}
	w.key("type")
	encStr(w, params.Type)
	w.key("body")
	encObject(w, params.Body)
	if params.Ext != nil {
		w.key("ext")
		encObject(w, params.Ext)
	}
	if params.Mentions != nil {
		w.key("mentions")
		encMentions(w, *params.Mentions)
	}
	if params.ReplyTo != nil {
		w.key("reply_to")
		encReplyTo(w, *params.ReplyTo)
	}
	if params.NeedReceipt {
		w.key("need_receipt")
		encBool(w, params.NeedReceipt)
	}
	if params.ExcludeFromUnread {
		w.key("exclude_from_unread")
		encBool(w, params.ExcludeFromUnread)
	}
	if params.Push != nil {
		w.key("push")
		encMessagePushOptions(w, *params.Push)
	}
	if params.OnlineOnly {
		w.key("online_only")
		encBool(w, params.OnlineOnly)
	}
	if params.SyncToSender != nil {
		w.key("sync_to_sender")
		encBool(w, *params.SyncToSender)
	}
	w.endObject()
	out := new(SendResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Export 按消息 ID 从旧到新导出应用的消息
//
// 服务端的视角：含已撤回、已擦除的消息（不含内容），超过保留期的跳过。只导出消息 ID 中的时间早于当前 30 秒的消息，
// 一页合计超过 1 MB 时提前结束。本页（跳过之前）的条数等于 limit 时 has_more 就为 true，下一页可能为空；是否结束只看 has_more。
// 要求逐条不漏的实时归档用回调模块的消息抄送。
//
// 接口：GET /messages（messages.export）。查询，网络错误、超时、5xx 时自动重试。
func (s *MessagesService) Export(ctx context.Context, params ExportParams) (*ExportPage, error) {
	c := s.t.newCall(&endpoints.MessagesExport)
	if params.AfterMessageID != "" {
		c.query("after_message_id", params.AfterMessageID)
	}
	if params.Limit != 0 {
		c.query("limit", strconv.Itoa(params.Limit))
	}
	out := new(ExportPage)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// BatchSend 批量发送单聊消息（每次最多应用的 max_recipients_per_message 个接收人）
//
// 以同一个发送者、同样的内容给每个接收人各发一条单聊消息，服务端的发送规则同 send。不能带 mentions、need_receipt、online_only
// （为未知字段，invalid_argument）和 reply_to（invalid_reply）。
// client_msg_id 必填，在每个接收人的会话中各用一次：已经写入过的接收人结果为 duplicate（不计入应用的消息数），用同一个 client_msg_id 重试是安全的。
// 逐个处理，整体返回 200，结果按 to_users 的顺序（重复的用户名各有一项，用户名与请求中的写法相同）。失败的项：not_found（用户不存在）、
// invalid_argument（self_conversation）、app_unavailable（只读状态）、rate_limited（app_message_rate：应用每分钟的消息数不够时超出的人失败，
// details 带 retry_after_seconds，可能只发出了一部分）、message_rejected（发送前检查只调用一次，拒绝时全部失败，替换时全部写入替换后的内容）。
// 按接收人数计入 OpenAPI 额度，额度不足时整个请求返回 rate_limited、任何一项都没有执行；from 不存在、被平台封禁和参数错误同样整个请求失败。
//
// 接口：POST /messages/batch（messages.batch_send）。带幂等键的写操作，用同一个键自动重试。
func (s *MessagesService) BatchSend(ctx context.Context, params BatchSendParams) (*BatchSendResult, error) {
	c := s.t.newCall(&endpoints.MessagesBatchSend)
	w := c.body()
	c.require(params.From != "", "from")
	c.require(len(params.ToUsers) > 0, "to_users")
	c.maxItems("to_users", len(params.ToUsers), 1000)
	c.maxItems("to_users", len(params.ToUsers), 1000)
	c.require(params.ClientMsgID != "", "client_msg_id")
	c.checkClientMsgID(params.ClientMsgID)
	c.require(params.Type != "", "type")
	c.require(params.Body != nil, "body")
	w.beginObject()
	w.key("from")
	encStr(w, params.From)
	w.key("to_users")
	encSlice(encStr)(w, params.ToUsers)
	w.key("client_msg_id")
	encStr(w, params.ClientMsgID)
	w.key("type")
	encStr(w, params.Type)
	w.key("body")
	encObject(w, params.Body)
	if params.Ext != nil {
		w.key("ext")
		encObject(w, params.Ext)
	}
	if params.ExcludeFromUnread {
		w.key("exclude_from_unread")
		encBool(w, params.ExcludeFromUnread)
	}
	if params.Push != nil {
		w.key("push")
		encMessagePushOptions(w, *params.Push)
	}
	if params.SyncToSender {
		w.key("sync_to_sender")
		encBool(w, params.SyncToSender)
	}
	w.endObject()
	c.items = len(params.ToUsers)
	out := new(BatchSendResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// BatchSendAll 按上限（1000 项）拆分、依次提交、合并结果；服务端以 too_many_items 给出更小的上限（应用的设置）时按它重新拆分。
// 某一批整体失败时停止，返回已完成部分的合并结果和那一批的错误；没有出现在结果中的项可以再提交一次。
// 各批用同一个 ClientMsgID（服务端按接收人去重），重试和重新提交都不会重复发送。
func (s *MessagesService) BatchSendAll(ctx context.Context, params BatchSendParams) (*BatchSendResult, error) {
	return batchAll(ctx, params.ToUsers, 1000, func(ctx context.Context, chunk []string) (*BatchSendResult, error) {
		p := params
		p.ToUsers = chunk
		return s.BatchSend(ctx, p)
	}, mergeBatchSend)
}

// BatchRecall 批量撤回消息（每次最多 100 条）
//
// 逐条撤回，规则同 recall，每条一个事务，某条失败（如 not_found）不影响其他条；结果按请求的顺序，重复的 ID 各有一项（后面的 changed 为 false）。
// 按条数计入 OpenAPI 额度，额度不足时整个请求返回 rate_limited、任何一条都没有执行。
//
// 接口：POST /messages/batch-recall（messages.batch_recall）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *MessagesService) BatchRecall(ctx context.Context, messageIDs []string, reason string) (*BatchRecallResult, error) {
	c := s.t.newCall(&endpoints.MessagesBatchRecall)
	w := c.body()
	c.require(len(messageIDs) > 0, "message_ids")
	c.maxItems("message_ids", len(messageIDs), 100)
	c.maxItems("message_ids", len(messageIDs), 100)
	w.beginObject()
	w.key("message_ids")
	encSlice(encStr)(w, messageIDs)
	if reason != "" {
		w.key("reason")
		encStr(w, reason)
	}
	w.endObject()
	c.items = len(messageIDs)
	out := new(BatchRecallResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Get 按 ID 读取消息
//
// 服务端的视角，任何会话的消息都可以读取；已撤回、已擦除的不含内容。不存在或超过保留期为 not_found。
//
// 接口：GET /messages/{message_id}（messages.get）。查询，网络错误、超时、5xx 时自动重试。
func (s *MessagesService) Get(ctx context.Context, messageID string) (*Message, error) {
	c := s.t.newCall(&endpoints.MessagesGet)
	c.path("message_id", messageID)
	out := new(Message)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Edit 编辑消息
//
// body、ext 至少给一个（都不给为 invalid_argument，empty_edit）。只能编辑 text、custom（其他类型为 permission_denied，not_editable），
// 已撤回、已擦除的为 permission_denied（message_recalled），已编辑 100 次为 limit_exceeded（edit_limit）。
// 新内容照常校验类型和大小，并经过内容安全和发消息前回调（可能被拒绝或替换）；@、引用、已读回执不能改。
// 内容与现在相同时不修改、changed 为 false（重试的结果相同）。只读状态下返回 app_unavailable。
//
// 接口：PATCH /messages/{message_id}（messages.edit）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *MessagesService) Edit(ctx context.Context, messageID string, params EditMessageParams) (*MessageChange, error) {
	c := s.t.newCall(&endpoints.MessagesEdit)
	c.path("message_id", messageID)
	w := c.body()
	w.beginObject()
	if params.Body != nil {
		w.key("body")
		encObject(w, params.Body)
	}
	writeField(w, "ext", params.Ext, encObject)
	if params.Reason != nil {
		w.key("reason")
		encStr(w, *params.Reason)
	}
	w.endObject()
	out := new(MessageChange)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Pin 置顶消息
//
// 不检查角色，pinned 的 by 为 null。已置顶的返回 200、changed 为 false。已撤回、已擦除的为 permission_denied（message_recalled），
// 会话中置顶的消息已达应用的 max_pinned_messages_per_conversation（默认 20）为 limit_exceeded（pinned_message_limit）。
// 只读状态下返回 app_unavailable。不存在或超过保留期为 not_found。
//
// 接口：PUT /messages/{message_id}/pin（messages.pin）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
