// AllSentBy 逐项遍历 SentBy 的结果，自动翻页：按 next_cursor 是否为空判断结束，不按条数判断（一页可能为空而仍有下一页）。
// 出错时产出这个错误后结束，已产出的项有效。
func (s *MessagesService) AllSentBy(ctx context.Context, username string, params SentByParams) iter.Seq2[Message, error] {
	return iterPages(ctx, params.Cursor, func(ctx context.Context, cursor string) ([]Message, string, error) {
		p := params
		p.Cursor = cursor
		page, err := s.SentBy(ctx, username, p)
		if err != nil {
			return nil, "", err
		}
		return page.Items, page.NextCursor, nil
	})
}

// ConversationsService 会话信息与消息，用户的会话状态、未读数、标记已读、删除与清空（client.Conversations）。
type ConversationsService struct {
	t *transport
}

// Get 查询会话信息
//
// 服务端的视角。群的会话 ID 即群 ID，还没有消息的群为 not_found。
//
// 接口：GET /conversations/{conversation_id}（conversations.get）。查询，网络错误、超时、5xx 时自动重试。
func (s *ConversationsService) Get(ctx context.Context, conversationID string) (*ConversationInfo, error) {
	c := s.t.newCall(&endpoints.ConversationsGet)
	c.path("conversation_id", conversationID)
	out := new(ConversationInfo)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Messages 按序号拉取会话中的消息
//
// 服务端的视角：看到全部消息，不受任何用户的删除、清空和可见范围影响，仍按保留期过滤；已撤回、已擦除的不含内容。结果都按序号从小到大。
// after_seq、before_seq、around_seq 至多给一个（多个为 invalid_argument，conflicting_params），都不给时为最新的一页；
// around_seq 取它本身、它之前的 limit / 2 条和之后的其余条数。
// start_time、end_time 把范围限定在这段时间内，可以与序号参数同时使用：只给时间时从时间段的起点向新的方向取（响应为 next_after_seq），
// 之后带上 after_seq 继续。一页最多扫描 1000 个序号、合计不超过 1 MB，可能为空而 has_more 为真；是否结束只看 has_more
// （按 around_seq 取时为两个方向各自的 has_more_before、has_more_after）。会话不存在为 not_found。
//
// 接口：GET /conversations/{conversation_id}/messages（conversations.messages）。查询，网络错误、超时、5xx 时自动重试。
func (s *ConversationsService) Messages(ctx context.Context, conversationID string, params SeqParams) (*SeqPage, error) {
	c := s.t.newCall(&endpoints.ConversationsMessages)
	c.path("conversation_id", conversationID)
	if countSet(params.AfterSeq, params.BeforeSeq, params.AroundSeq) > 1 {
		c.fail("after_seq", "AfterSeq、BeforeSeq、AroundSeq 至多给一个")
	}
	if params.AfterSeq != nil {
		c.query("after_seq", strconv.FormatInt(*params.AfterSeq, 10))
	}
	if params.BeforeSeq != nil {
		c.query("before_seq", strconv.FormatInt(*params.BeforeSeq, 10))
	}
	if params.AroundSeq != nil {
		c.query("around_seq", strconv.FormatInt(*params.AroundSeq, 10))
	}
	if !params.StartTime.IsZero() {
		c.query("start_time", formatTime(params.StartTime))
	}
	if !params.EndTime.IsZero() {
		c.query("end_time", formatTime(params.EndTime))
	}
	if params.Limit != 0 {
		c.query("limit", strconv.Itoa(params.Limit))
	}
	out := new(SeqPage)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Pins 分页列出会话中置顶的消息
//
// 服务端的视角，按置顶时间从新到旧，超过保留期的跳过。没有 limit，一页合计不超过 1 MB，超过时给出 next_cursor。会话不存在为 not_found。
//
// 接口：GET /conversations/{conversation_id}/pins（conversations.pins）。查询，网络错误、超时、5xx 时自动重试。
func (s *ConversationsService) Pins(ctx context.Context, conversationID, cursor string) (*Page[Message], error) {
	c := s.t.newCall(&endpoints.ConversationsPins)
	c.path("conversation_id", conversationID)
	if cursor != "" {
		c.query("cursor", cursor)
	}
	out := new(Page[Message])
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// AllPins 逐项遍历 Pins 的结果，自动翻页：按 next_cursor 是否为空判断结束，不按条数判断（一页可能为空而仍有下一页）。
// 出错时产出这个错误后结束，已产出的项有效。
func (s *ConversationsService) AllPins(ctx context.Context, conversationID string) iter.Seq2[Message, error] {
	return iterPages(ctx, "", func(ctx context.Context, cursor string) ([]Message, string, error) {
		page, err := s.Pins(ctx, conversationID, cursor)
		if err != nil {
			return nil, "", err
		}
		return page.Items, page.NextCursor, nil
	})
}

