// MediaService 文件的上传与下载、文件信息、群文件、存储用量（client.Media）。
type MediaService struct {
	t *transport
}

// DownloadURLs 换取下载地址（每次最多 100 个）
//
// 按输入的顺序逐项给出下载地址或错误，同一个地址可以出现多次，只计一次额度。单项的错误：not_found（不是本服务的文件地址、
// 不属于本应用、密钥不对、还在上传中、头像的公开地址、非图片的缩略图地址）、file_expired（已过期或已删除）、file_blocked（已被屏蔽）。
// 下载地址 60 到 90 分钟有效，同一个文件在同一个 30 分钟内得到相同的地址；不要保存或写进消息。不检查群成员身份。
//
// 接口：POST /media/download-urls（media.download_urls）。查询，网络错误、超时、5xx 时自动重试。
func (s *MediaService) DownloadURLs(ctx context.Context, urls []string) ([]DownloadURLItem, error) {
	c := s.t.newCall(&endpoints.MediaDownloadURLs)
	w := c.body()
	c.require(len(urls) > 0, "urls")
	c.maxItems("urls", len(urls), 100)
	w.beginObject()
	w.key("urls")
	encSlice(encStr)(w, urls)
	w.endObject()
	var out struct {
		Value []DownloadURLItem `json:"items"`
	}
	if err := s.t.do(ctx, c, &out); err != nil {
		return nil, err
	}
	return out.Value, nil
}

