// ModerationService 内容安全：配置、词库、文本检查、审核记录与结论、举报、违规（client.Moderation）。
type ModerationService struct {
	t *transport
}

// Config 查询应用的内容安全配置
//
// scenes 含全部场景的有效设置（没有设置过的为默认值）；还没有配置过的应用返回默认值、version 为 1、updated_at 为 null。
// platform 为平台对本应用的设置，只读。
//
// 接口：GET /moderation/config（moderation.config）。查询，网络错误、超时、5xx 时自动重试。
func (s *ModerationService) Config(ctx context.Context) (*ModerationConfig, error) {
	c := s.t.newCall(&endpoints.ModerationConfig)
	out := new(ModerationConfig)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// UpdateConfig 修改应用的内容安全配置
//
// 只修改给出的字段，没有改变任何值时版本号不变。给出 version 时与当前不一致返回 version_conflict（details.current 为 {version, updated_at}）。
// 场景不支持的检查方式返回 invalid_argument（unsupported_scene）；开启第三方审核而控制台没有选择审核账号返回 invalid_argument（provider_account_required）；
// penalty_rules 超过 5 条返回 limit_exceeded（penalty_rule_limit）。审核账号 provider_account_id 只能在控制台选择，platform 部分只读，读到的配置不能原样提交。
//
// 接口：PATCH /moderation/config（moderation.update_config）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *ModerationService) UpdateConfig(ctx context.Context, params UpdateModerationConfigParams) (*ModerationConfig, error) {
	c := s.t.newCall(&endpoints.ModerationUpdateConfig)
	w := c.body()
	w.beginObject()
	if params.Scenes != nil {
		w.key("scenes")
		encMap(encModerationSceneUpdate)(w, params.Scenes)
	}
	if params.CustomMessageCheck != nil {
		w.key("custom_message_check")
		encStr(w, *params.CustomMessageCheck)
	}
	if params.CategoryActions != nil {
		w.key("category_actions")
		encFieldMap(encModerationCategoryActionUpdate)(w, params.CategoryActions)
	}
	if params.SyncTimeoutMs != nil {
		w.key("sync_timeout_ms")
		encInt64(w, *params.SyncTimeoutMs)
	}
	if params.OnTimeout != nil {
		w.key("on_timeout")
		encStr(w, *params.OnTimeout)
	}
	writeField(w, "penalty_rules", params.PenaltyRules, encSlice(encPenaltyRule))
	if params.Version != nil {
		w.key("version")
		encInt64(w, *params.Version)
	}
	if params.Reason != nil {
		w.key("reason")
		encStr(w, *params.Reason)
	}
	w.endObject()
	out := new(ModerationConfig)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Items 分页列出租户队列的审核记录
//
// 不含内容和 actions。默认只列未结束的（pending、auto_violation），列未结束的状态时按优先级（0 最高）、再按 ID 从新到旧，只列已结束的状态时只按 ID。
// 按作者筛选时用户不存在得到空页。
//
// 接口：GET /moderation/items（moderation.items）。查询，网络错误、超时、5xx 时自动重试。
func (s *ModerationService) Items(ctx context.Context, params ListItemsParams) (*Page[ModerationItem], error) {
	c := s.t.newCall(&endpoints.ModerationItems)
	for _, v := range params.Status {
		c.query("status", v)
	}
	if params.Scene != "" {
		c.query("scene", params.Scene)
	}
	if params.TargetType != "" {
		c.query("target_type", params.TargetType)
	}
	if params.Category != "" {
		c.query("category", params.Category)
	}
	if params.Source != "" {
		c.query("source", params.Source)
	}
	if params.Author != "" {
		c.query("author", params.Author)
	}
	if params.Priority != nil {
		c.query("priority", strconv.FormatInt(*params.Priority, 10))
	}
	if !params.From.IsZero() {
		c.query("from", formatTime(params.From))
	}
	if !params.To.IsZero() {
		c.query("to", formatTime(params.To))
	}
	if params.Escalated != nil {
		c.query("escalated", strconv.FormatBool(*params.Escalated))
	}
	if params.Order != "" {
		c.query("order", params.Order)
	}
	if params.Cursor != "" {
		c.query("cursor", params.Cursor)
	}
	if params.Limit != 0 {
		c.query("limit", strconv.Itoa(params.Limit))
	}
	out := new(Page[ModerationItem])
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// AllItems 逐项遍历 Items 的结果，自动翻页：按 next_cursor 是否为空判断结束，不按条数判断（一页可能为空而仍有下一页）。
// 出错时产出这个错误后结束，已产出的项有效。
func (s *ModerationService) AllItems(ctx context.Context, params ListItemsParams) iter.Seq2[ModerationItem, error] {
	return iterPages(ctx, params.Cursor, func(ctx context.Context, cursor string) ([]ModerationItem, string, error) {
		p := params
		p.Cursor = cursor
		page, err := s.Items(ctx, p)
		if err != nil {
			return nil, "", err
		}
		return page.Items, page.NextCursor, nil
	})
}

// BatchDecide 批量作出同样的结论（每次最多 100 条）
//
// 逐条处理，某条失败不影响其他的，整体返回 200；失败的项在 error 中。不能带 mute_user、disable_user、disable_group、disable_chatroom（整个请求返回 invalid_argument、invalid_action）。
// 已结束的记录（超时结束的除外）单项为 version_conflict（details.current 为记录），重试后 SDK 把结论与本次相同的这种单项按成功处理。按项数计入 OpenAPI 额度。
//
// 接口：POST /moderation/items/batch-decide（moderation.batch_decide）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *ModerationService) BatchDecide(ctx context.Context, params BatchDecideParams) (*BatchDecideResult, error) {
	c := s.t.newCall(&endpoints.ModerationBatchDecide)
	w := c.body()
	c.require(len(params.ItemIDs) > 0, "item_ids")
	c.maxItems("item_ids", len(params.ItemIDs), 100)
	c.maxItems("item_ids", len(params.ItemIDs), 100)
	c.require(params.Decision != "", "decision")
	w.beginObject()
	w.key("item_ids")
	encSlice(encStr)(w, params.ItemIDs)
	w.key("decision")
	encStr(w, params.Decision)
	if params.Actions != nil {
		w.key("actions")
		encSlice(encModerationActionInput)(w, params.Actions)
	}
	if params.CountViolation != nil {
		w.key("count_violation")
		encBool(w, *params.CountViolation)
	}
	if params.Note != "" {
		w.key("note")
		encStr(w, params.Note)
	}
	w.endObject()
	c.items = len(params.ItemIDs)
	c.after = func(out any, attempts int) { fixBatchDecide(out.(*BatchDecideResult), params.Decision, attempts) }
	out := new(BatchDecideResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Item 查询审核记录（含它引起的处置）
//
// 不含内容。平台队列中没有转交的记录返回 not_found。
//
// 接口：GET /moderation/items/{item_id}（moderation.item）。查询，网络错误、超时、5xx 时自动重试。
func (s *ModerationService) Item(ctx context.Context, itemID string) (*ModerationItem, error) {
	c := s.t.newCall(&endpoints.ModerationItem)
	c.path("item_id", itemID)
	out := new(ModerationItem)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// ItemContent 读取审核记录的内容和举报
//
// content 的结构随对象的类型不同：消息为 type、body、ext、created_at、edits、review_urls；资料为 fields；文件为 file_id、kind、name、review_urls；
// 用户、群、聊天室为 profile、versions。快照已清空（记录结束 30 天后）时为 null。review_urls 的查看地址 10 分钟内有效，平台规则屏蔽的文件为 null。
// OpenAPI 的读取不写操作日志、不按人限流。
//
// 接口：GET /moderation/items/{item_id}/content（moderation.item_content）。查询，网络错误、超时、5xx 时自动重试。
func (s *ModerationService) ItemContent(ctx context.Context, itemID string) (*ItemContent, error) {
	c := s.t.newCall(&endpoints.ModerationItemContent)
	c.path("item_id", itemID)
	out := new(ItemContent)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Decide 作出结论或改判
//
// actions 只用于 violation，按对象允许的处置，否则返回 invalid_argument（invalid_action）。给出 version 时与当前不一致返回 version_conflict（details.current 为记录）。
// 记录已是这个结论、由同一凭据作出且没有带 actions 的，直接返回当前记录（不检查 version）；带 actions 而没有 version 的重复请求会再执行一次处置，
// 所以不自动重试，超时后用 get_item 查看 decision 和 actions 再决定。
// 已转交平台、平台作出的结论、无违规改为违规、违规改判超过 30 天、因转交或对象删除而结束的，返回 permission_denied（not_revisable）。处置提交后异步执行，响应中为 pending。
//
// 接口：POST /moderation/items/{item_id}/decide（moderation.decide）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。带 Actions 而没有 Version 时按不幂等处理，不自动重试（服务端会重复执行处置）。
func (s *ModerationService) Decide(ctx context.Context, itemID string, params DecideParams) (*ModerationItem, error) {
	c := s.t.newCall(&endpoints.ModerationDecide)
	c.path("item_id", itemID)
	c.unsafe = len(params.Actions) > 0 && params.Version == nil
	w := c.body()
	c.require(params.Decision != "", "decision")
	w.beginObject()
	w.key("decision")
	encStr(w, params.Decision)
	if params.Actions != nil {
		w.key("actions")
		encSlice(encModerationActionInput)(w, params.Actions)
	}
	if params.CountViolation != nil {
		w.key("count_violation")
		encBool(w, *params.CountViolation)
	}
	if params.Note != "" {
		w.key("note")
		encStr(w, params.Note)
	}
	if params.Version != nil {
		w.key("version")
		encInt64(w, *params.Version)
	}
	w.endObject()
	out := new(ModerationItem)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Escalate 把租户队列中未结束的记录转交平台
//
// 平台队列中已有同一对象未结束的记录时合并到那一条，原记录改为 expired（close_reason 为 escalated），返回平台那一条（item_id 与请求的不同）。
// 已转交或已结束的返回 permission_denied（not_revisable），所以不自动重试；超时后用 get_item 查看原记录：escalated_at 不为 null 或 close_reason 为 escalated 即已转交。
//
// 接口：POST /moderation/items/{item_id}/escalate（moderation.escalate）。不幂等：请求发出后不自动重试（被限流的照常等待后重发），超时后先查询结果再决定是否重试。
func (s *ModerationService) Escalate(ctx context.Context, itemID, note string) (*ModerationItem, error) {
	c := s.t.newCall(&endpoints.ModerationEscalate)
	c.path("item_id", itemID)
	w := c.body()
	w.beginObject()
	if note != "" {
		w.key("note")
		encStr(w, note)
	}
	w.endObject()
	out := new(ModerationItem)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// PlatformActions 分页列出平台对本应用执行的处置
//
// 只读，按时间倒序；不含内容、记录 ID 和平台的操作人。
