// CreateStream 开始一条流式回复（底层接口，通常用 StartStream）
//
// 以机器人的身份给用户写入一条 status 为 streaming 的 ai 消息。按 client_stream_id 去重：重复提交返回 200 和已有的流（不论是否已结束），
// 没有给时 SDK 生成。会话中已有进行中的回复返回 stream_in_progress（details.stream_id），replace 为真时先把它结束为 stopped（replaced）。
// 机器人停用为 permission_denied（bot_disabled），用户拉黑了机器人为 user_blocked，进行中的回复数已达上限为 limit_exceeded（bot_active_streams）。
//
// 接口：POST /ai/streams（ai.create_stream）。带幂等键的写操作，用同一个键自动重试。
func (s *AIService) CreateStream(ctx context.Context, bot, to string, params CreateStreamParams) (*AICreateStreamResult, error) {
	c := s.t.newCall(&endpoints.AICreateStream)
	w := c.body()
	c.require(bot != "", "bot")
	c.require(to != "", "to")
	w.beginObject()
	w.key("bot")
	encStr(w, bot)
	w.key("to")
	encStr(w, to)
	if params.ReplyToSeq != nil {
		w.key("reply_to_seq")
		encInt64(w, *params.ReplyToSeq)
	}
	clientStreamID := params.ClientStreamID
	c.checkClientMsgID(clientStreamID)
	if clientStreamID == "" && !c.unsafe {
		clientStreamID = newClientMsgID()
	}
	if clientStreamID != "" {
		w.key("client_stream_id")
		encStr(w, clientStreamID)
	}
	if params.Replace {
		w.key("replace")
		encBool(w, params.Replace)
	}
	w.endObject()
	out := new(AICreateStreamResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// GetStream 查询流
//
// 生成中和结束 10 分钟内带 content（累积的片段）。
//
// 接口：GET /ai/streams/{stream_id}（ai.get_stream）。查询，网络错误、超时、5xx 时自动重试。
func (s *AIService) GetStream(ctx context.Context, streamID string) (*AIGetStreamResult, error) {
	c := s.t.newCall(&endpoints.AIGetStream)
	c.path("stream_id", streamID)
	out := new(AIGetStreamResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// WriteDeltas 按批写入增量（底层接口，通常用 Stream 的写入方法）
//
// 一次最多 100 段、64 KB。已接受过的段跳过；序号不连续返回 seq_gap（details.expected_seq）；流已结束返回 stream_closed；
// 累积内容超过 1 MB 时流以 failed（too_large）结束并返回 payload_too_large（content）。
//
// 接口：POST /ai/streams/{stream_id}/deltas:batch（ai.write_deltas）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *AIService) WriteDeltas(ctx context.Context, streamID string, deltas []AIDelta) (*AIWriteDeltasResult, error) {
	c := s.t.newCall(&endpoints.AIWriteDeltas)
	c.path("stream_id", streamID)
	w := c.body()
	c.require(len(deltas) > 0, "deltas")
	w.beginObject()
	w.key("deltas")
	encSlice(encAIDelta)(w, deltas)
	w.endObject()
	out := new(AIWriteDeltasResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// FailStream 报告失败（生成中断）
//
// 以 failed（developer）结束，已生成的部分保留；客户端显示 message。流已结束返回 stream_closed。
//
// 接口：POST /ai/streams/{stream_id}/fail（ai.fail_stream）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *AIService) FailStream(ctx context.Context, streamID, code, message string) (*AIFailStreamResult, error) {
	c := s.t.newCall(&endpoints.AIFailStream)
	c.path("stream_id", streamID)
	w := c.body()
	c.require(code != "", "code")
	w.beginObject()
	w.key("code")
	encStr(w, code)
	if message != "" {
		w.key("message")
		encStr(w, message)
	}
	w.endObject()
	out := new(AIFailStreamResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// FinishStream 结束流（已完成）
//
// last_seq 必须等于已接受的最后一段，否则返回 seq_gap；流已结束返回 stream_closed。
//
// 接口：POST /ai/streams/{stream_id}/finish（ai.finish_stream）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *AIService) FinishStream(ctx context.Context, streamID string, lastSeq int64, params FinishStreamParams) (*AIFinishStreamResult, error) {
	c := s.t.newCall(&endpoints.AIFinishStream)
	c.path("stream_id", streamID)
	w := c.body()
	w.beginObject()
	w.key("last_seq")
	encInt64(w, lastSeq)
	if params.FinishReason != "" {
		w.key("finish_reason")
		encStr(w, params.FinishReason)
	}
	if params.Model != "" {
		w.key("model")
		encStr(w, params.Model)
	}
	if params.Usage != nil {
		w.key("usage")
		encAIUsage(w, *params.Usage)
	}
	w.endObject()
	out := new(AIFinishStreamResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// GameService 游戏房间：建房、签加入票据、开局、结束、移出玩家，成员与大区（client.Game）。
type GameService struct {
	t *transport
}

// ListRegions 列出可以建房的大区
//
// 已启用的大区和是否有可调度的游戏节点；default 为应用的默认大区（应用没有设置时为平台默认大区）。
//
// 接口：GET /game/regions（game.list_regions）。查询，网络错误、超时、5xx 时自动重试。
func (s *GameService) ListRegions(ctx context.Context) ([]GameRegion, error) {
	c := s.t.newCall(&endpoints.GameListRegions)
	var out struct {
		Value []GameRegion `json:"items"`
	}
	if err := s.t.do(ctx, c, &out); err != nil {
		return nil, err
	}
	return out.Value, nil
}

// ListRooms 分页列出游戏房间
//
// 按创建时间从新到旧；status 可以是逗号分隔的多个状态，不传时为全部；search 按房间 ID 前缀匹配。
//
// 接口：GET /game/rooms（game.list_rooms）。查询，网络错误、超时、5xx 时自动重试。
func (s *GameService) ListRooms(ctx context.Context, params ListGameRoomsParams) (*Page[GameRoom], error) {
	c := s.t.newCall(&endpoints.GameListRooms)
	if params.Status != "" {
		c.query("status", params.Status)
	}
	if params.Search != "" {
		c.query("search", params.Search)
	}
	if params.Cursor != "" {
		c.query("cursor", params.Cursor)
	}
	if params.Limit != 0 {
		c.query("limit", strconv.Itoa(params.Limit))
	}
	out := new(Page[GameRoom])
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

// AllRooms 逐项遍历 ListRooms 的结果，自动翻页：按 next_cursor 是否为空判断结束，不按条数判断（一页可能为空而仍有下一页）。
// 出错时产出这个错误后结束，已产出的项有效。
func (s *GameService) AllRooms(ctx context.Context, params ListGameRoomsParams) iter.Seq2[GameRoom, error] {
	return iterPages(ctx, params.Cursor, func(ctx context.Context, cursor string) ([]GameRoom, string, error) {
		p := params
		p.Cursor = cursor
		page, err := s.ListRooms(ctx, p)
		if err != nil {
			return nil, "", err
		}
		return page.Items, page.NextCursor, nil
	})
}

// CreateRoom 创建游戏房间
//
// 以业务的房间 ID 创建房间并分配到游戏节点。同参数重复调用返回同一房间（200，created 为假）；参数不同或房间已结束返回
// conflict（room_id_used）。同时进行的房间数已达上限返回 limit_exceeded（open_rooms）；当前大区没有可用节点返回
// unavailable（game_capacity_unavailable，可以稍后重试）。
//
// 接口：PUT /game/rooms/{room_id}（game.create_room）。本身幂等，可以自动重试；重试后得到 not_found、version_conflict 时错误的 Retried 为真。
func (s *GameService) CreateRoom(ctx context.Context, roomID string, params CreateGameRoomParams) (*GameCreateRoomResult, error) {
	c := s.t.newCall(&endpoints.GameCreateRoom)
	c.path("room_id", roomID)
	w := c.body()
	w.beginObject()
	if params.Name != "" {
		w.key("name")
		encStr(w, params.Name)
	}
	if params.Region != "" {
		w.key("region")
		encStr(w, params.Region)
	}
	if params.Regions != nil {
		w.key("regions")
		encSlice(encStr)(w, params.Regions)
	}
	if params.MaxPlayers != nil {
		w.key("max_players")
		encInt64(w, *params.MaxPlayers)
	}
	if params.SyncMode != "" {
		w.key("sync_mode")
		encStr(w, params.SyncMode)
	}
	if params.TickRate != nil {
		w.key("tick_rate")
		encInt64(w, *params.TickRate)
	}
	if params.StartMode != "" {
		w.key("start_mode")
		encStr(w, params.StartMode)
	}
	if params.AccessMode != "" {
		w.key("access_mode")
		encStr(w, params.AccessMode)
	}
	if params.MaxDurationSeconds != nil {
		w.key("max_duration_seconds")
		encInt64(w, *params.MaxDurationSeconds)
	}
	if params.ReconnectWindowSeconds != nil {
		w.key("reconnect_window_seconds")
		encInt64(w, *params.ReconnectWindowSeconds)
	}
	if params.Snapshot != nil {
		w.key("snapshot")
		encGameRoomSnapshotParams(w, *params.Snapshot)
	}
	if params.Ext != nil {
		w.key("ext")
		encObject(w, params.Ext)
	}
	w.endObject()
	out := new(GameCreateRoomResult)
	if err := s.t.do(ctx, c, out); err != nil {
		return nil, err
	}
	return out, nil
}

